-- Variables
local STARTING_ID = 80000
local ALL_CHARACTERS_LIST = {"Illusion Team", "Magic Team", "Devil Team", "Nether Team", "Reimu", "Yukari", "Marisa", "Alice", "Sakuya", "Remilia", "Youmu", "Yuyuko"}
local STAGES_LIST = {
	{"Wriggle - Midboss", "Wriggle Defeated", "Wriggle - Last Spell"},
	{"Mystia - Midboss", "Mystia Defeated", "Mystia - Last Spell"},
	{"Keine - Midboss 1", "Keine Defeated", "Keine - Last Spell"},
	{"Reimu - Midboss", "Reimu Defeated", "Reimu - Last Spell"},
	{"Marisa - Midboss", "Marisa Defeated", "Marisa - Last Spell"},
	{"Tewi Defeated", "Reisen Defeated", "Reisen - Last Spell"},
	{"Eirin - Midboss 1", "Eirin Defeated"},
	{"Eirin - Midboss 2", "Kaguya Defeated"},
	{"Keine - Midboss 2", "Mokou Defeated"}
}
local DIFFICULTY_LIST = {"Easy", "Normal", "Hard", "Lunatic"}

local locations_data = {}
local location_id_offset = 0

LOCATION_MAPPING = {}

for _, character in ipairs(ALL_CHARACTERS_LIST) do
	local level = 0
	for _, stage in ipairs(STAGES_LIST) do
		level = level + 1
		local stage_name = tostring(level)
		local is_extra = (level == 9)

		if level == 4 then
			stage_name = "4A"
		elseif level == 5 then
			stage_name = "4B"
		elseif level == 6 then
			stage_name = "5"
		elseif level == 7 then
			stage_name = "6A"
		elseif level == 8 then
			stage_name = "6B"
		elseif level == 9 then
			stage_name = "Extra"
		end

		for _, check in ipairs(stage) do
			local id = STARTING_ID + location_id_offset

			locations_data[id] = {
				character = character,
				stage = stage_name,
				check = check,
				has_difficulty = false,
				is_stage_clear = false,
				is_extra = is_extra
			}

			location_id_offset = location_id_offset + 1
		end

		-- Stage clear entry
		local id = STARTING_ID + location_id_offset
		locations_data[id] = {
			character = character,
			stage = stage_name,
			check = "Stage " .. stage_name .. " Clear",
			has_difficulty = false,
			is_stage_clear = true,
			is_extra = is_extra
		}

		location_id_offset = location_id_offset + 1
	end
end

-- Generate locations with difficulty
for _, difficulty in ipairs(DIFFICULTY_LIST) do
	for _, character in ipairs(ALL_CHARACTERS_LIST) do
		local level = 0
		for _, stage in ipairs(STAGES_LIST) do
			level = level + 1
			local stage_name = tostring(level)

			if level == 4 then
				stage_name = "4A"
			elseif level == 5 then
				stage_name = "4B"
			elseif level == 6 then
				stage_name = "5"
			elseif level == 7 then
				stage_name = "6A"
			elseif level == 8 then
				stage_name = "6B"
			elseif level == 9 then
				stage_name = "Extra"
			end

			-- Skip conditions
			if not (stage_name == "Extra") then
				for _, check in ipairs(stage) do
					if not (string.find(check, "Last Spell") and  difficulty == "Easy") then
						local id = STARTING_ID + location_id_offset

						locations_data[id] = {
							character = character,
							stage = stage_name,
							check = check,
							has_difficulty = true,
							difficulty = difficulty,
							is_stage_clear = false,
							is_extra = (level == 9)
						}

						location_id_offset = location_id_offset + 1
					end
				end
			end
		end
	end
end

for id, data in pairs(locations_data) do
	local character = data.character
	local has_difficulty = data.has_difficulty
	local is_stage_clear = data.is_stage_clear
	local is_extra = data.is_extra

	local team_no_difficulty = "@teamNoDifficulty"
	local team_has_difficulty = "@teamHasDifficulty"
	local solo_no_difficulty = "@soloNoDifficulty"
	local solo_has_difficulty = "@soloHasDifficulty"

	local is_team = true

	if character == "Reimu" or character == "Marisa" or character == "Yukari" or character == "Alice" or character == "Sakuya" or character == "Remilia" or character == "Youmu" or character == "Yuyuko" then
		is_team = false
	end


	-- Generate the path string
	local pathStr
	if has_difficulty then
		pathStr = string.format("/[%s] Stage %s/[%s][%s] %s",
			character, data.stage,
			data.difficulty, character, data.check)

		-- Add to the LOCATION_MAPPING table
		if is_team then
			LOCATION_MAPPING[id] = {team_has_difficulty .. pathStr}
		else
			LOCATION_MAPPING[id] = {solo_has_difficulty .. pathStr}
		end
	else
		pathStr = string.format("/[%s] Stage %s/[%s] %s",
			character, data.stage, character, data.check)

		-- For Stage Clear locations, Extra Stage or Phantasm Stage locations, include both difficulty and non-difficulty prefixes
		if is_stage_clear or is_extra then
			if is_team then
				LOCATION_MAPPING[id] = {
					team_no_difficulty .. pathStr,
					team_has_difficulty .. pathStr
				}
			else
				LOCATION_MAPPING[id] = {
					solo_no_difficulty .. pathStr,
					solo_has_difficulty .. pathStr
				}
			end
		else
			-- Normal locations without difficulty
			if is_team then
				LOCATION_MAPPING[id] = {team_no_difficulty .. pathStr}
			else
				LOCATION_MAPPING[id] = {solo_no_difficulty .. pathStr}
			end
		end
	end
end

